userDefinedLinkHintCss:
/* Catppuccin Mocha -- https://github.com/catppuccin/catppuccin */

/* LINK HINTS (f) */
div > .vimiumHintMarker {
  padding: 2px 3px;
  background-color: #1e1e2e;
  border: 1px solid #45475a;
  border-radius: 3px;
  box-shadow: 0em 0.1em 0.6em 0.1em rgba(17, 17, 27, 0.5);
  background-image: none;
}

div > .vimiumHintMarker span {
  font-size: 12px;
  font-family: MesloLGM Nerd Font;
  font-weight: bold;
  text-shadow: none;
  color: #cba6f7;
}

/* Already-typed characters dim so the remaining hint stays prominent. */
div > .vimiumHintMarker > .matchingCharacter {
  color: #6c7086;
}

/* Hints still matching what you've typed get a brighter border. */
div > .vimiumActiveHintMarker {
  border-color: #74c7ec;
}

/* VOMNIBAR (o / b / T) */
#vomnibar {
  background-color: #1e1e2e;
}

#vomnibar input {
  color: #cdd6f4;
  font-weight: normal;
  font-size: 20px;
  font-family: MesloLGM Nerd Font;
  height: 34px;
  margin-bottom: 0;
  padding: 4px;
  background-color: #11111b;
  border-radius: 3px;
  border: 1px solid #45475a;
  box-shadow: #585b70 0px 0px 1px;
  width: 100%;
  outline: none;
  box-sizing: border-box;
}

#vomnibar .vomnibarSearchArea {
  display: block;
  padding: 10px;
  background-color: #181825;
  border-radius: 4px 4px 0 0;
  border-bottom: 1px solid #45475a;
}

#vomnibar ul {
  background-color: #1e1e2e;
  border-radius: 0 0 4px 4px;
  list-style: none;
  padding-top: 0;
  padding-bottom: 0;
  margin-block-start: 2px;
  margin-block-end: 0px;
}

#vomnibar li {
  border-bottom: 1px solid #313244;
  line-height: 1.1em;
  padding: 7px 10px;
  font-size: 16px;
  color: #cdd6f4;
  position: relative;
  display: list-item;
  margin: auto;
}

#vomnibar li .vomnibarBottomHalf {
  font-size: 15px;
  margin-top: 3px;
  padding: 2px 0;
}

#vomnibar li .vomnibarSource {
  color: #74c7ec;
  margin-right: 4px;
}

#vomnibar li .vomnibarRelevancy {
  position: absolute;
  right: 0;
  top: 0;
  padding: 5px;
  background-color: #181825;
  color: #a6adc8;
  font-family: MesloLGM Nerd Font Mono;
  width: 100px;
  overflow: hidden;
}

#vomnibar li .vomnibarUrl {
  color: #89b4fa;
}

#vomnibar li .vomnibarMatch {
  font-weight: bold;
  color: #fab387;
}

#vomnibar li.vomnibarSelected {
  background-color: #313244;
}

#vomnibar li em, #vomnibar li .vomnibarTitle {
  color: #cdd6f4;
  margin-left: 4px;
  font-weight: normal;
}

#vomnibar li em {
  font-style: italic;
}

#vomnibar li em .vomnibarMatch,
#vomnibar li .vomnibarTitle .vomnibarMatch {
  color: #fab387;
}

#vomnibarInput::selection {
  background-color: #45475a;
}
